// NewSankey calls <gpui_kit::base::plot::shape::Sankey>::new.
func NewSankey() Sankey {
	n := rt.NewValue(536)
	return Sankey{Val: rt.MkVal(n)}
}

// NewSankeyDefault calls <gpui_kit::base::plot::shape::Sankey as Default>::default.
func NewSankeyDefault() Sankey {
	n := rt.NewValue(535)
	return Sankey{Val: rt.MkVal(n)}
}

// Set the layout bounds as `[x0, y0, x1, y1]`. Defaults to `[0, 0, 1, 1]`.
//
// Extent calls <gpui_kit::base::plot::shape::Sankey>::extent.
func (e Sankey) Extent(x0 float32, y0 float32, x1 float32, y1 float32) Sankey {
	o := rt.Op(rt.N(e.Core), 256)
	o.F32(x0)
	o.F32(y0)
	o.F32(x1)
	o.F32(y1)
	return e
}

// Set the number of relaxation passes. Defaults to 6.
//
// Iterations calls <gpui_kit::base::plot::shape::Sankey>::iterations.
func (e Sankey) Iterations(iterations int) Sankey {
	o := rt.Op(rt.N(e.Core), 257)
	rt.PutUsize(o, iterations)
	return e
}

// Set the node alignment. Defaults to `Justify`.
//
// NodeAlign calls <gpui_kit::base::plot::shape::Sankey>::node_align.
func (e Sankey) NodeAlign(align SankeyAlign) Sankey {
	o := rt.Op(rt.N(e.Core), 258)
	o.U16(uint16(align))
	return e
}

// Set the vertical gap between nodes in a column. Defaults to 8.
//
// NodePadding calls <gpui_kit::base::plot::shape::Sankey>::node_padding.
func (e Sankey) NodePadding(nodePadding float32) Sankey {
	o := rt.Op(rt.N(e.Core), 259)
	o.F32(nodePadding)
	return e
}

// Set the node rectangle width. Defaults to 24.
//
// NodeWidth calls <gpui_kit::base::plot::shape::Sankey>::node_width.
func (e Sankey) NodeWidth(nodeWidth float32) Sankey {
	o := rt.Op(rt.N(e.Core), 260)
	o.F32(nodeWidth)
	return e
}

// Equivalent to `extent(0., 0., width, height)`.
//
// Size calls <gpui_kit::base::plot::shape::Sankey>::size.
func (e Sankey) Size(width float32, height float32) Sankey {
	o := rt.Op(rt.N(e.Core), 261)
	o.F32(width)
	o.F32(height)
	return e
}

// Set how values map to heights. Defaults to `Linear`.
//
// ValueScale calls <gpui_kit::base::plot::shape::Sankey>::value_scale.
func (e Sankey) ValueScale(valueScale SankeyValueScale) Sankey {
	o := rt.Op(rt.N(e.Core), 262)
	o.U16(uint16(valueScale))
	return e
}

// SankeyLink is gpui_kit::base::plot::shape::SankeyLink.
type SankeyLink struct{ rt.Val }

// Create a link from the `source` node index to the `target` node index carrying `value`.
//
// NewSankeyLink calls <gpui_kit::base::plot::shape::SankeyLink>::new.
func NewSankeyLink(source int, target int, value float64) SankeyLink {
	n := rt.NewValue(537)
	o := rt.NodeArgs(n)
	rt.PutUsize(o, source)
	rt.PutUsize(o, target)
	o.F64(value)
	return SankeyLink{Val: rt.MkVal(n)}
}
